#!/usr/bin/env bash
# Installs the vLLM-SR workshop (lab 01) on a lab VM so it starts by itself at every boot.
# Run once while preparing the image:  sudo bash vllm_sr_lab_install.sh
#
# Generated by make-installer.sh from installer-template.sh and setup.sh; edit those, not this file.
#
# Each lab instance gets its own endpoint and key from the lab platform: a lifecycle action
# writes them to /etc/vllm-sr-lab.env at launch. Nothing secret is stored in the image.
#   FOUNDRY_ENDPOINT=<full chat completions URL>
#   FOUNDRY_API_KEY=<this instance's key>
#   ROUTINE_DEPLOYMENT=<optional; default FW-Qwen3.8-27B>
#   REASONING_DEPLOYMENT=<optional; default FW-GLM-5.3-Flash>
# Only these names (and FOUNDRY_PATH) are read; the file is parsed, never executed.
#
# At boot the service waits for that file, exports the values to every new terminal
# (/etc/profile.d/vllm-sr-lab.sh), runs ~/setup.sh, and writes ~/WORKSHOP-READY.txt with the
# links and the Dashboard login; at desktop login the notebook opens in the browser as soon as
# that file appears. Log: /var/log/vllm-sr-lab.log
# Before committing the image, run: sudo vllm-sr-lab-scrub
set -euo pipefail
[ "$(id -u)" = 0 ] || { echo "run with sudo"; exit 1; }
LAB_USER="${LAB_USER:-${SUDO_USER:-}}"
[ -n "$LAB_USER" ] && [ "$LAB_USER" != root ] || { echo "run with sudo from the lab user's account (or set LAB_USER)"; exit 1; }
LAB_HOME="$(getent passwd "$LAB_USER" | cut -d: -f6)"
[ -d "$LAB_HOME" ] || { echo "no home directory for $LAB_USER"; exit 1; }

# setup.sh (sha f8a02e712fb7); written in place so its owner stays the lab user.
cat > "$LAB_HOME/setup.sh" <<'VLLM_SR_SETUP_SH'
#!/usr/bin/env bash
# vLLM-SR workshop on a CPU-only lab VM: model lanes on Azure Foundry, d3-lite routing on the CPU.
# Run with: bash ~/setup.sh   (FOUNDRY_ENDPOINT and FOUNDRY_API_KEY must be set)
set -euo pipefail

# The tested workshop image, pinned by digest (Router, Dashboard, d3-lite, relay, JupyterLab, Hermes).
IMAGE='mahatri/vllm-sr-agent-workshop@sha256:22965e265cba00861855ecb95013a6512da8a24207f108033755928d5d59752f'
# Notebook files come from this branch (or a tag: REF=tags/<name>); if GitHub is unreachable,
# the container uses the copy shipped in the image.
OWNER='Mahdi-CV'; REPO='amd-gpu-workshops'
REF="${REF:-heads/workshop/vllm-sr-route-one-agent-v3-foundry-cpu-d3}"
SUB='notebooks/vllm-sr-route-one-agent-v3'
DEST="$HOME/workshop"
MIN_FREE_GB=10   # the image is 3.9 GB

# Same Dashboard login on every VM; export either variable to override.
DASH_EMAIL="${DASHBOARD_ADMIN_EMAIL:-admin@workshop.local}"
DASH_PASS="${DASHBOARD_ADMIN_PASSWORD:-workshop2026}"

if [ -z "${FOUNDRY_ENDPOINT:-}" ] || [ -z "${FOUNDRY_API_KEY:-}" ]; then
  echo "Set FOUNDRY_ENDPOINT and FOUNDRY_API_KEY (from the lab instructions panel) first"; exit 1
fi

echo "== machine"
lsb_release -ds 2>/dev/null || true
echo "CPU: $(lscpu | sed -n 's/^Model name:[[:space:]]*//p')  x$(nproc)   RAM: $(free -g | awk '/Mem:/{print $2}') GB"

# 1. Docker installed and usable?
if ! command -v docker >/dev/null; then
  echo "== installing docker"
  sudo apt-get update -y
  sudo apt-get install -y docker.io
  sudo systemctl enable --now docker
fi
DOCKER=docker
if ! docker info >/dev/null 2>&1; then
  sudo systemctl start docker 2>/dev/null || true
  if sudo docker info >/dev/null 2>&1; then DOCKER='sudo docker'; else
    echo "Docker is installed but not responding"; exit 1; fi
fi
$DOCKER version --format 'Docker {{.Server.Version}} ({{.Server.Os}}/{{.Server.Arch}})'

# 2. Pull the image, unless it is already here
if $DOCKER image inspect "$IMAGE" >/dev/null 2>&1; then
  echo "== image already present"
else
  ROOT=$($DOCKER info -f '{{.DockerRootDir}}')
  FREE=$(df -BG --output=avail "$ROOT" | tail -1 | tr -dc 0-9)
  echo "== free on $ROOT: ${FREE} GB (need ${MIN_FREE_GB})"
  if [ "$FREE" -lt "$MIN_FREE_GB" ]; then
    echo "Not enough disk for the image; stopping before the pull."; df -h; exit 1
  fi
  echo "== pulling $IMAGE"
  $DOCKER pull "$IMAGE"
fi

# 3. Notebook files, once: a rerun keeps the student's edits.
if [ -f "$DEST/workshop_lab.py" ]; then
  echo "== workshop files already present, keeping them: $DEST"
else
  mkdir -p "$DEST"
  TMP=$(mktemp -d)
  if curl -fsSL "https://codeload.github.com/$OWNER/$REPO/tar.gz/refs/$REF" | tar -xz -C "$TMP" 2>/dev/null \
     && [ -f "$TMP"/*/"$SUB"/workshop_lab.py ]; then
    cp -r "$TMP"/*/"$SUB"/route-one-agent-across-two-models-v3.ipynb \
          "$TMP"/*/"$SUB"/workshop_lab.py "$TMP"/*/"$SUB"/agent-demo "$DEST"/
    echo "== workshop files from GitHub ($REF)"
  else
    echo "== GitHub unreachable; the container will use the copy in the image"
  fi
  rm -rf "$TMP"
fi

# 4. The workshop container. Host networking: everything listens on this VM's 127.0.0.1 only
#    (JupyterLab 8888, Dashboard 9000, routed API 8898, relay 8001/8002).
echo "== starting the workshop"
# Values are passed explicitly: `sudo docker -e NAME` would read sudo's (empty) environment.
ENVS=(-e "FOUNDRY_ENDPOINT=$FOUNDRY_ENDPOINT" -e "FOUNDRY_API_KEY=$FOUNDRY_API_KEY"
      -e "DASHBOARD_ADMIN_EMAIL=$DASH_EMAIL" -e "DASHBOARD_ADMIN_PASSWORD=$DASH_PASS")
for v in FOUNDRY_PATH ROUTINE_DEPLOYMENT REASONING_DEPLOYMENT; do
  if [ -n "${!v:-}" ]; then ENVS+=(-e "$v=${!v}"); fi
done
$DOCKER rm -f vllm-sr >/dev/null 2>&1 || true
$DOCKER run -d --name vllm-sr --network host "${ENVS[@]}" -v "$DEST:/workspace" "$IMAGE" >/dev/null

echo "== waiting for the Router (d3-lite loads on the CPU), Dashboard and JupyterLab"
ready=0
for _ in $(seq 1 300); do
  if $DOCKER exec vllm-sr sh -c 'curl -fsS -m 3 -o /dev/null http://127.0.0.1:8898/v1/models \
      && curl -fsS -m 3 -o /dev/null http://127.0.0.1:9000 \
      && curl -fsS -m 3 -o /dev/null http://127.0.0.1:8888/api/status' 2>/dev/null; then ready=1; break; fi
  if ! $DOCKER ps -q --filter name=^vllm-sr$ | grep -q .; then break; fi
  sleep 2
done
$DOCKER exec vllm-sr cat /workspace/logs/start-platform.log 2>/dev/null || $DOCKER logs --tail 20 vllm-sr
[ "$ready" = 1 ] || { echo "The workshop did not become ready; see the log above and: docker logs vllm-sr"; exit 1; }

echo "== relay check (one real call per model)"
for p in 8002 8001; do
  echo "port $p:"
  $DOCKER exec vllm-sr python3 -c "import json,urllib.request as u
r=u.Request('http://127.0.0.1:$p/v1/chat/completions',data=json.dumps({'messages':[{'role':'user','content':'Say OK'}],'max_tokens':8}).encode(),headers={'Content-Type':'application/json'})
try: print(u.urlopen(r,timeout=60).read()[:300].decode())
except Exception as e: print('FAILED:', e, getattr(e,'read',lambda:b'')()[:300])" || true
done

echo
echo "Open http://localhost:8888/lab in the browser on this VM."
echo "Dashboard: http://localhost:9000"
echo "Dashboard login: $DASH_EMAIL / $DASH_PASS"
VLLM_SR_SETUP_SH
chown "$LAB_USER": "$LAB_HOME/setup.sh"
echo "setup.sh sha: $(sha256sum "$LAB_HOME/setup.sh" | cut -c1-12) (expected f8a02e712fb7)"

cat > /usr/local/bin/vllm-sr-lab-start <<'VLLM_SR_START'
#!/usr/bin/env bash
# Boot-time start for the vLLM-SR workshop; installed by vllm_sr_lab_install.sh.
set -u
ENV_FILE="${VLLM_SR_ENV_FILE:-/etc/vllm-sr-lab.env}"
PROFILE="${VLLM_SR_PROFILE:-/etc/profile.d/vllm-sr-lab.sh}"
LAB_USER="${VLLM_SR_LAB_USER:-labuser}"
LAB_HOME="${VLLM_SR_LAB_HOME:-$(getent passwd "$LAB_USER" | cut -d: -f6)}"
SETUP="${VLLM_SR_SETUP:-$LAB_HOME/setup.sh}"
WAIT_SECONDS="${VLLM_SR_WAIT_SECONDS:-1800}"
READY="$LAB_HOME/WORKSHOP-READY.txt"
NAMES="FOUNDRY_ENDPOINT FOUNDRY_API_KEY FOUNDRY_PATH ROUTINE_DEPLOYMENT REASONING_DEPLOYMENT"
LOGIN="admin@workshop.local / workshop2026"   # the Dashboard login setup.sh sets

echo "$(date -u +%FT%TZ) start: waiting up to ${WAIT_SECONDS}s for $ENV_FILE"
rm -f "$READY"
waited=0
while [ ! -s "$ENV_FILE" ] && [ "$waited" -lt "$WAIT_SECONDS" ]; do
  sleep 5; waited=$((waited + 5))
done
[ -s "$ENV_FILE" ] || { echo "no $ENV_FILE after ${WAIT_SECONDS}s; not starting"; exit 1; }

# Read NAME=value lines without executing the file, so a value can hold any character.
while IFS= read -r line || [ -n "$line" ]; do
  line="${line%$'\r'}"
  case "$line" in ''|'#'*) continue ;; esac
  name="${line%%=*}"; value="${line#*=}"
  name="${name#export }"
  case "$value" in \"*\") value="${value:1:${#value}-2}" ;; \'*\') value="${value:1:${#value}-2}" ;; esac
  case " $NAMES " in
    *" $name "*) export "$name=$value"; echo "  read $name" ;;
    *) echo "  ignored $name" ;;
  esac
done < "$ENV_FILE"
for v in FOUNDRY_ENDPOINT FOUNDRY_API_KEY; do
  [ -n "${!v:-}" ] || { echo "$ENV_FILE has no $v; not starting"; exit 1; }
done
export ROUTINE_DEPLOYMENT="${ROUTINE_DEPLOYMENT:-FW-Qwen3.8-27B}"
export REASONING_DEPLOYMENT="${REASONING_DEPLOYMENT:-FW-GLM-5.3-Flash}"

# Every new terminal gets the same values, so `bash ~/setup.sh` also works by hand.
umask 022
{
  echo "# Written at boot by vllm-sr-lab-start from $ENV_FILE; do not edit."
  for v in $NAMES; do
    [ -n "${!v:-}" ] && printf 'export %s=%q\n' "$v" "${!v}"
  done
} > "$PROFILE"
chmod 644 "$PROFILE"

export HOME="$LAB_HOME"
cd "$LAB_HOME" || exit 1
echo "$(date -u +%FT%TZ) running $SETUP (routine: $ROUTINE_DEPLOYMENT, reasoning: $REASONING_DEPLOYMENT)"
bash "$SETUP"
rc=$?
echo "$(date -u +%FT%TZ) setup exited $rc"
[ "$rc" = 0 ] || exit "$rc"

printf 'The workshop is running.\n\nJupyterLab:  http://localhost:8888/lab\nDashboard:   http://localhost:9000\nDashboard login: %s\n' "$LOGIN" > "$READY"
chown "$LAB_USER": "$READY" 2>/dev/null || true
echo "$(date -u +%FT%TZ) ready: $READY"
VLLM_SR_START
chmod 755 /usr/local/bin/vllm-sr-lab-start

cat > /usr/local/bin/vllm-sr-lab-scrub <<VLLM_SR_SCRUB
#!/usr/bin/env bash
# Clears per-instance state before the image is committed: key file, exported values, the
# running workshop, the workshop folder (it is filled again at launch) and shell history.
# Keeps the workshop image, ~/setup.sh and the boot service.
set -u
[ "\$(id -u)" = 0 ] || { echo "run with sudo"; exit 1; }
systemctl stop vllm-sr-lab.service 2>/dev/null || true
docker rm -f vllm-sr >/dev/null 2>&1 || true
rm -f /etc/vllm-sr-lab.env /etc/profile.d/vllm-sr-lab.sh "$LAB_HOME/WORKSHOP-READY.txt" /var/log/vllm-sr-lab.log
rm -rf "$LAB_HOME/workshop"
# Left over from the earlier GPU-image workshop, if present.
rm -f "$LAB_HOME/foundry_proxy.py" "$LAB_HOME/.vllm_sr_dashboard"
rm -f "$LAB_HOME/.bash_history" /root/.bash_history
echo "scrubbed; workshop image kept: \$(docker image ls --format '{{.Repository}}@{{.Digest}}' | grep vllm-sr-agent-workshop | head -1)"
echo "now close the terminal (its history is in memory) and commit"
VLLM_SR_SCRUB
chmod 755 /usr/local/bin/vllm-sr-lab-scrub

# At desktop login: wait until the workshop is ready, then open the notebook in the browser,
# so the student only has to log in.
cat > /usr/local/bin/vllm-sr-lab-open <<'VLLM_SR_OPEN'
#!/usr/bin/env bash
# Opens the workshop notebook once ~/WORKSHOP-READY.txt appears (up to 20 minutes).
URL="http://localhost:8888/lab/tree/route-one-agent-across-two-models-v3.ipynb"
for _ in $(seq 1 240); do
  [ -f "$HOME/WORKSHOP-READY.txt" ] && break
  sleep 5
done
[ -f "$HOME/WORKSHOP-READY.txt" ] || exit 0
sleep 3
xdg-open "$URL" >/dev/null 2>&1 || firefox "$URL" >/dev/null 2>&1 &
VLLM_SR_OPEN
chmod 755 /usr/local/bin/vllm-sr-lab-open
mkdir -p /etc/xdg/autostart
cat > /etc/xdg/autostart/vllm-sr-lab-open.desktop <<'VLLM_SR_DESKTOP'
[Desktop Entry]
Type=Application
Name=vLLM-SR Workshop
Comment=Opens the workshop notebook when it is ready
Exec=/usr/local/bin/vllm-sr-lab-open
X-GNOME-Autostart-enabled=true
NoDisplay=true
VLLM_SR_DESKTOP

cat > /etc/systemd/system/vllm-sr-lab.service <<VLLM_SR_UNIT
[Unit]
Description=vLLM-SR workshop (waits for this instance's endpoint and key, then starts)
Wants=network-online.target
After=network-online.target docker.service

[Service]
Type=oneshot
RemainAfterExit=yes
Environment=VLLM_SR_LAB_USER=$LAB_USER
ExecStart=/usr/local/bin/vllm-sr-lab-start
StandardOutput=append:/var/log/vllm-sr-lab.log
StandardError=append:/var/log/vllm-sr-lab.log
TimeoutStartSec=0

[Install]
WantedBy=multi-user.target
VLLM_SR_UNIT

systemctl daemon-reload
systemctl enable vllm-sr-lab.service
echo "installed for $LAB_USER: ~/setup.sh, vllm-sr-lab.service (starts at boot), vllm-sr-lab-scrub"
echo "test now: write /etc/vllm-sr-lab.env, then: sudo systemctl restart vllm-sr-lab; tail -f /var/log/vllm-sr-lab.log"
